hooks.command:
python -c 'import json,os,sys; d=json.load(sys.stdin); p=d.get("tool_input",{}).get("file_path",""); b=os.path.basename(p);
if b.startswith(".env"):
 print(json.dumps({"systemMessage":"⚠️  警告：正在修改环境变量文件，请确认操作安全性","hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"ask","permissionDecisionReason":"Protected environment file"}}))'

python -c 'import fnmatch,json,os,shlex,sys; d=json.load(sys.stdin); tool=d.get("tool_name",""); ti=d.get("tool_input",{}); paths=[]
if tool in ("Edit","Write"):
 paths.append(ti.get("file_path",""))
elif tool == "Bash":
 cmd=ti.get("command","")
 try:
  parts=shlex.split(cmd)
 except ValueError:
  parts=cmd.split()
 if parts and os.path.basename(parts[0]) == "rm":
  paths.extend(parts[1:])

def protected(p):
 p=p.replace("\\","/")
 return fnmatch.fnmatch(p, "backend/*_results.json") or fnmatch.fnmatch(p, "*/backend/*_results.json")
if any(protected(p) for p in paths):
 print(json.dumps({"systemMessage":"⚠️  警告：正在修改评测结果文件，这可能影响实验数据完整性","hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"ask","permissionDecisionReason":"Protected benchmark results file"}}))'
